package com.flowdesk.alert.recovery;
import com.flowdesk.alert.event.TicketResultConsumer;import com.flowdesk.alert.service.AlertCursorTokenService;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;import org.springframework.transaction.PlatformTransactionManager;
@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(prefix="flowdesk.alert.ticket-result.entry",name="enabled",havingValue="true")class AlertRecoveryConfiguration{@Bean AlertRecoveryRepository alertRecoveryRepository(JdbcTemplate j){return new AlertRecoveryRepository(j);}@Bean(name="alertRecoveryExecutor")ThreadPoolTaskExecutor alertRecoveryExecutor(){var e=new ThreadPoolTaskExecutor();e.setCorePoolSize(1);e.setMaxPoolSize(1);e.setQueueCapacity(100);e.setThreadNamePrefix("alert-recovery-");e.setWaitForTasksToCompleteOnShutdown(true);return e;}@Bean AlertRecoveryWorker alertRecoveryWorker(@Qualifier("alertRecoveryExecutor")ThreadPoolTaskExecutor e,AlertRecoveryRepository r,TicketResultConsumer c,PlatformTransactionManager tx){return new AlertRecoveryWorker(e,r,c,tx);}@Bean AlertRecoveryService alertRecoveryService(AlertRecoveryRepository r,AlertCursorTokenService c,PlatformTransactionManager tx,AlertRecoveryWorker w){return new AlertRecoveryService(r,c,tx,w);}}
